/**
 * F2 + F3 -- patient profile and history (BUILD_ROADMAP C3).
 *
 * NEXT 16: `params` is a PROMISE. Synchronous access was removed entirely,
 * not merely deprecated, so `params.id` returns undefined rather than
 * failing loudly. `PageProps<'/patients/[id]'>` is generated by
 * `next typegen` and types the awaited shape, so the route string and the
 * param name are checked against the actual file tree.
 *
 * A server component that awaits the param and hands it to a client
 * component for the data. The alternative -- fetching here -- would put the
 * API URL and its error handling on the server, where the C1 error states
 * and React Query's retry cannot reach it.
 */
import { PatientProfile } from '@/components/patient/patient-profile'

export default async function PatientPage({ params }: PageProps<'/patients/[id]'>) {
  const { id } = await params

  return <PatientProfile patientId={id} />
}
